using System;
using System.Drawing;
using System.Drawing.Drawing2D;
using System.Drawing.Imaging;
using System.IO;
using System.Runtime.InteropServices;

namespace NaiwaDesktopPet
{
    // High-resolution source poses, registered to the same body footprint.
    // Motion is generated by the rigs; no legacy GIF decoder or frame blender.
    public sealed class AnimationClip : IDisposable
    {
        public readonly Bitmap Frame;
        public readonly int Duration;
        readonly string state;
        readonly BlinkRig blinkRig;
        readonly Bitmap restExhaleFrame;
        public bool UsesCalmListeningPose { get { return state == "listen"; } }
        public bool UsesHdIdlePose { get { return state == "idle"; } }
        public bool UsesSharedBodyLaugh { get { return state == "laugh"; } }
        public bool UsesHdRestPose { get { return state == "rest"; } }
        public bool HasBlink { get { return blinkRig != null; } }
        public int SourceWidth { get; private set; }
        public int SourceHeight { get; private set; }
        internal Bitmap RestExhaleFrame { get { return restExhaleFrame; } }

        public AnimationClip(string directory, string state)
        {
            this.state = state;
            string template = Path.Combine(directory, "reference-footprint.png");
            Duration = state == "rest" ? 1000 : state == "laugh" ? 3000 : 4000;
            if (state == "laugh")
            {
                using (var original = Image.FromFile(Path.Combine(directory, "idle-hd-reference-match.png")))
                using (var expression = Image.FromFile(Path.Combine(directory, "laugh-peak-expression.png")))
                using (var body = CopyRegisteredIdle(original, template))
                using (var face = CopyRegisteredIdle(expression, template))
                {
                    SourceWidth = original.Width; SourceHeight = original.Height;
                    Frame = ComposeSharedBodyLaugh(body, face);
                }
                return;
            }
            string file;
            float widthRatio = 1, heightRatio = 1;
            switch (state)
            {
                case "idle": file = "idle-hd-reference-match.png"; break;
                case "listen": file = "listen-thinking.png"; widthRatio = 1.25f; heightRatio = .80f; break;
                case "rest": file = "rest-supine.png"; widthRatio = 2.0f; heightRatio = .62f; break;
                default: throw new ArgumentException("Unknown pet animation.", "state");
            }
            using (var original = Image.FromFile(Path.Combine(directory, file)))
            {
                SourceWidth = original.Width; SourceHeight = original.Height;
                Frame = CopyRegisteredPose(original, template, widthRatio, heightRatio);
                blinkRig = new BlinkRig(original, Frame, state, image => CopyRegisteredPose(image, template, widthRatio, heightRatio), directory);
            }
            if (state == "rest")
                using (var exhale = Image.FromFile(Path.Combine(directory, "rest-exhale-mouth.png")))
                    restExhaleFrame = CopyRegisteredPose(exhale, template, widthRatio, heightRatio);
        }

        static int FaceEndY(Bitmap body)
        { var bounds = VisibleBounds(body); return bounds.Top + (int)Math.Ceiling(bounds.Height * .32); }

        static Bitmap ComposeSharedBodyLaugh(Bitmap body, Bitmap expression)
        {
            // Keep the idle body's alpha and all pixels below the face intact.
            // A generated expression can never replace the torso or legs again.
            if (body.Size != expression.Size) throw new InvalidDataException("Face and body caches must share a size.");
            byte[] basis = ReadPixels(body), face = ReadPixels(expression);
            var result = new Bitmap(body.Width, body.Height, PixelFormat.Format32bppPArgb);
            var bounds = VisibleBounds(body);
            int fadeStart = bounds.Top + (int)Math.Floor(bounds.Height * .23);
            int fadeEnd = FaceEndY(body);
            for (int y = bounds.Top; y < fadeEnd; y++)
            {
                int weight = y <= fadeStart ? 256 : (fadeEnd - y) * 256 / Math.Max(1, fadeEnd - fadeStart);
                for (int x = 0; x < body.Width; x++)
                {
                    int pixel = (y * body.Width + x) * 4;
                    int alpha = basis[pixel + 3], faceAlpha = face[pixel + 3];
                    if (alpha == 0 || faceAlpha < 32) continue;
                    for (int channel = 0; channel < 3; channel++)
                    {
                        int color = Math.Min(alpha, (face[pixel + channel] * alpha + faceAlpha / 2) / faceAlpha);
                        basis[pixel + channel] = (byte)((basis[pixel + channel] * (256 - weight) + color * weight + 128) >> 8);
                    }
                }
            }
            var data = result.LockBits(new Rectangle(0, 0, result.Width, result.Height), ImageLockMode.WriteOnly, PixelFormat.Format32bppPArgb);
            try { Marshal.Copy(basis, 0, data.Scan0, basis.Length); }
            finally { result.UnlockBits(data); }
            return result;
        }

        public static string ValidateSharedBody(string directory)
        {
            using (var idle = new AnimationClip(directory, "idle"))
            using (var laugh = new AnimationClip(directory, "laugh"))
            {
                Bitmap body = idle.Frame, laughing = laugh.Frame;
                if (body.Size != laughing.Size) throw new InvalidDataException("Laugh changed the body canvas size.");
                byte[] a = ReadPixels(body), b = ReadPixels(laughing);
                int faceEnd = FaceEndY(body), faceChanges = 0, preservedBodyPixels = 0;
                for (int y = 0; y < body.Height; y++)
                for (int x = 0; x < body.Width; x++)
                {
                    int pixel = (y * body.Width + x) * 4;
                    if (a[pixel + 3] != b[pixel + 3]) throw new InvalidDataException("Laugh changed the idle silhouette.");
                    bool changed = a[pixel] != b[pixel] || a[pixel + 1] != b[pixel + 1] || a[pixel + 2] != b[pixel + 2];
                    if (y >= faceEnd)
                    {
                        if (changed) throw new InvalidDataException("Laugh changed torso, belly, arms or legs.");
                        if (a[pixel + 3] > 0) preservedBodyPixels++;
                    }
                    else if (changed) faceChanges++;
                }
                if (faceChanges < 32) throw new InvalidDataException("Laughter expression is missing.");
                return "Shared-body check passed: identical alpha silhouette; " + preservedBodyPixels
                    + " unchanged torso/limb pixels; " + faceChanges + " changed facial pixels.";
            }
        }

        internal static Rectangle VisibleBounds(Image image)
        {
            using (var bitmap = new Bitmap(image.Width, image.Height, PixelFormat.Format32bppPArgb))
            {
                using (var g = Graphics.FromImage(bitmap))
                { g.CompositingMode = CompositingMode.SourceCopy; g.DrawImageUnscaled(image, 0, 0); }
                byte[] bytes = ReadPixels(bitmap);
                int left = image.Width, top = image.Height, right = -1, bottom = -1;
                for (int y = 0; y < image.Height; y++)
                {
                    int rowLeft = image.Width, rowRight = -1, count = 0;
                    for (int x = 0; x < image.Width; x++)
                        if (bytes[(y * image.Width + x) * 4 + 3] >= 128)
                        { count++; rowLeft = Math.Min(rowLeft, x); rowRight = x; }
                    if (count < Math.Max(3, image.Width / 150)) continue;
                    left = Math.Min(left, rowLeft); right = Math.Max(right, rowRight);
                    top = Math.Min(top, y); bottom = y;
                }
                if (right < left || bottom < top) throw new InvalidDataException("Idle reference has no visible character.");
                return Rectangle.FromLTRB(left, top, right + 1, bottom + 1);
            }
        }

        static Bitmap CopyRegisteredIdle(Image image, string templatePath)
        { return CopyRegisteredPose(image, templatePath, 1, 1); }

        static Bitmap CopyRegisteredPose(Image image, string templatePath, float widthRatio, float heightRatio)
        {
            // The generated PNG may have different transparent margins. Fit its
            // visible figure to the original frame's footprint, without changing
            // its anatomy or enlarging the entire pet along with the head.
            int edge = Math.Max(240, (int)Math.Ceiling(240 * DisplayQuality.Scale));
            Rectangle source = VisibleBounds(image);
            var result = new Bitmap(edge, edge, PixelFormat.Format32bppPArgb);
            using (var template = Image.FromFile(templatePath))
            using (var g = Graphics.FromImage(result))
            using (var attributes = new ImageAttributes())
            {
                Rectangle reference = VisibleBounds(template);
                float scale = Math.Min((float)reference.Width * edge / template.Width / source.Width * widthRatio,
                    (float)reference.Height * edge / template.Height / source.Height * heightRatio);
                float width = source.Width * scale, height = source.Height * scale;
                float x = (reference.Left + reference.Width / 2f) * edge / template.Width - width / 2;
                float y = (float)reference.Bottom * edge / template.Height - height;
                g.CompositingMode = CompositingMode.SourceCopy;
                g.InterpolationMode = InterpolationMode.HighQualityBicubic;
                g.PixelOffsetMode = PixelOffsetMode.HighQuality;
                attributes.SetWrapMode(WrapMode.TileFlipXY);
                g.DrawImage(image, Rectangle.Round(new RectangleF(x, y, width, height)), source.X, source.Y,
                    source.Width, source.Height, GraphicsUnit.Pixel, attributes);
            }
            return result;
        }

        internal static byte[] ReadPixels(Bitmap bitmap)
        {
            var data = bitmap.LockBits(new Rectangle(0, 0, bitmap.Width, bitmap.Height), ImageLockMode.ReadOnly, PixelFormat.Format32bppPArgb);
            try
            {
                var bytes = new byte[data.Stride * data.Height];
                Marshal.Copy(data.Scan0, bytes, 0, bytes.Length); return bytes;
            }
            finally { bitmap.UnlockBits(data); }
        }

        public Bitmap WithBlink(double closure) { return blinkRig == null ? Frame : blinkRig.At(closure); }
        public string ValidateBlink(string name) { return blinkRig == null ? "" : blinkRig.Validate(name); }
        public void Dispose()
        {
            if (restExhaleFrame != null) restExhaleFrame.Dispose();
            if (blinkRig != null) blinkRig.Dispose();
            Frame.Dispose();
        }
    }
}
